class GrandParent {
    public void greet() {
        System.out.println("Greetings from GrandParent");
    }
}

class ParentTier extends GrandParent {
    @Override
    public void greet() {
        super.greet();
        System.out.println("  -> and ParentTier");
    }
}

class ChildTier extends ParentTier {
    @Override
    public void greet() {
        super.greet();
        System.out.println("    -> and ChildTier!");
    }
}

public class DispatchTraceDemo {
    public static void main(String[] args) {
        // Superclass reference holding Leaf object
        GrandParent ref = new ChildTier();

        // Invocation routes to ChildTier.greet() dynamically
        ref.greet();
    }
}

