class ShapeDrawer {
    public void draw() { System.out.println("Generic shape"); }
    public void draw(int thickness) { System.out.println("Shape with thickness " + thickness); }
}

class CircleDrawer extends ShapeDrawer {
    @Override
    public void draw() { System.out.println("Circle: perfect curve"); }
    // Overload in subclass
    public void draw(String color) { System.out.println(color + " Circle"); }
}

public class OverloadOverrideTrace {
    public static void main(String[] args) {
        ShapeDrawer s = new CircleDrawer();
        s.draw();       // Overridden: dynamic dispatch calls CircleDrawer
        s.draw(5);      // Inherited overload: calls ShapeDrawer.draw(int)
        // s.draw("Red"); // COMPILE ERROR: ShapeDrawer does not declare draw(String)!
    }
}

