class TaxPolicy {
    public double computeTax(double gross) {
        return gross * 0.10;
    }
}

class StateTaxPolicy extends TaxPolicy {
    @Override
    public double computeTax(double gross) {
        return super.computeTax(gross) + (gross * 0.05);
    }
}

class LuxuryTaxPolicy extends StateTaxPolicy {
    @Override
    public double computeTax(double gross) {
        return super.computeTax(gross) + (gross * 0.08);
    }
}

public class TaxApp {
    public static void main(String[] args) {
        TaxPolicy[] policies = new TaxPolicy[] {
            new TaxPolicy(),
            new StateTaxPolicy(),
            new LuxuryTaxPolicy()
        };
        for (TaxPolicy p : policies) {
            System.out.println("Tax: $" + p.computeTax(1000.0));
        }
    }
}

