interface PipelineStage {
    String process(String input);
}

class BaseStage implements PipelineStage {
    @Override
    public String process(String input) {
        return input.toLowerCase();
    }
}

class SanitizingStage extends BaseStage {
    @Override
    public String process(String input) {
        return super.process(input).replaceAll("[^a-z0-9 ]", "");
    }
}

class PrefixStage extends SanitizingStage {
    private String prefix;
    public PrefixStage(String prefix) {
        this.prefix = prefix;
    }
    @Override
    public String process(String input) {
        return prefix + ": " + super.process(input);
    }
}

public class PipelineTraceApp {
    public static void main(String[] args) {
        PipelineStage stage = new PrefixStage("CLEAN_DATA");
        String result = stage.process("*** Hello World #2026! ***");
        System.out.println("Result: " + result);
    }
}
